<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kanban Board</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
      background: #f4f5f7;
      min-height: 100vh;
      padding: 24px;
    }

    .board {
      display: flex;
      gap: 16px;
      max-width: 1200px;
      margin: 0 auto;
      height: calc(100vh - 48px);
      min-height: 600px;
    }

    .column {
      flex: 1;
      background: #ebecf0;
      border-radius: 12px;
      display: flex;
      flex-direction: column;
      min-width: 0;
      box-shadow: 0 1px 2px rgba(9, 30, 66, 0.15);
    }

    .column-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 16px 8px;
      font-weight: 600;
      font-size: 14px;
      color: #172b4d;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .column-header .count {
      background: #0052cc;
      color: white;
      font-size: 12px;
      font-weight: 600;
      padding: 2px 8px;
      border-radius: 12px;
      min-width: 24px;
      text-align: center;
    }

    .column-cards {
      flex: 1;
      overflow-y: auto;
      padding: 0 8px 16px;
      display: flex;
      flex-direction: column;
      gap: 8px;
      min-height: 100px;
    }

    .column-cards.drag-over {
      background: rgba(0, 82, 204, 0.08);
      border-radius: 8px;
    }

    .card {
      background: white;
      border-radius: 8px;
      padding: 12px;
      box-shadow: 0 1px 2px rgba(9, 30, 66, 0.15);
      cursor: grab;
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 8px;
      transition: box-shadow 0.15s ease, transform 0.15s ease;
      border: 1px solid #dfe1e6;
    }

    .card:hover {
      box-shadow: 0 4px 8px rgba(9, 30, 66, 0.15);
      transform: translateY(-1px);
    }

    .card.dragging {
      opacity: 0.5;
      cursor: grabbing;
      box-shadow: 0 8px 16px rgba(9, 30, 66, 0.2);
    }

    .card-title {
      flex: 1;
      font-size: 14px;
      color: #172b4d;
      line-height: 1.4;
      word-wrap: break-word;
      padding-right: 8px;
    }

    .card-del {
      background: transparent;
      border: none;
      color: #6b778c;
      cursor: pointer;
      padding: 4px;
      border-radius: 4px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      transition: background-color 0.15s ease, color 0.15s ease;
      line-height: 1;
    }

    .card-del:hover {
      background: #ffebe9;
      color: #de350b;
    }

    .card-del:focus-visible {
      outline: 2px solid #0052cc;
      outline-offset: 2px;
    }

    .add-card-form {
      display: flex;
      gap: 8px;
      padding: 16px;
      max-width: 400px;
      margin: 0 auto 24px;
    }

    #new-card {
      flex: 1;
      padding: 10px 14px;
      border: 1px solid #dfe1e6;
      border-radius: 8px;
      font-size: 14px;
      color: #172b4d;
      background: white;
      transition: border-color 0.15s ease, box-shadow 0.15s ease;
    }

    #new-card:focus {
      outline: none;
      border-color: #0052cc;
      box-shadow: 0 0 0 3px rgba(0, 82, 204, 0.15);
    }

    #new-card::placeholder {
      color: #6b778c;
    }

    #add-card {
      background: #0052cc;
      color: white;
      border: none;
      border-radius: 8px;
      padding: 10px 20px;
      font-size: 14px;
      font-weight: 500;
      cursor: pointer;
      transition: background-color 0.15s ease;
      white-space: nowrap;
    }

    #add-card:hover {
      background: #0065ff;
    }

    #add-card:active {
      background: #0043a3;
    }

    #add-card:focus-visible {
      outline: 2px solid #0052cc;
      outline-offset: 2px;
    }

    @media (max-width: 768px) {
      .board {
        flex-direction: column;
        height: auto;
        min-height: auto;
      }

      .column {
        min-height: 300px;
      }
    }
  </style>
</head>
<body>
  <div class="add-card-form">
    <input type="text" id="new-card" placeholder="Enter card title..." aria-label="New card title">
    <button id="add-card" type="button">Add Card</button>
  </div>

  <div class="board">
    <section class="column" id="col-todo" data-column="todo">
      <header class="column-header">
        <span>To Do</span>
        <span class="count">0</span>
      </header>
      <div class="column-cards" id="cards-todo"></div>
    </section>

    <section class="column" id="col-doing" data-column="doing">
      <header class="column-header">
        <span>Doing</span>
        <span class="count">0</span>
      </header>
      <div class="column-cards" id="cards-doing"></div>
    </section>

    <section class="column" id="col-done" data-column="done">
      <header class="column-header">
        <span>Done</span>
        <span class="count">0</span>
      </header>
      <div class="column-cards" id="cards-done"></div>
    </section>
  </div>

  <script>
    (function() {
      'use strict';

      // State
      let cards = [];
      let draggedCard = null;

      // DOM Elements
      const newCardInput = document.getElementById('new-card');
      const addCardBtn = document.getElementById('add-card');
      const columns = {
        todo: document.getElementById('cards-todo'),
        doing: document.getElementById('cards-doing'),
        done: document.getElementById('cards-done')
      };
      const columnElements = {
        todo: document.getElementById('col-todo'),
        doing: document.getElementById('col-doing'),
        done: document.getElementById('col-done')
      };

      // Generate unique ID
      function generateId() {
        return Date.now().toString(36) + Math.random().toString(36).substr(2, 9);
      }

      // Create card element
      function createCardElement(card) {
        const cardEl = document.createElement('div');
        cardEl.className = 'card';
        cardEl.draggable = true;
        cardEl.dataset.id = card.id;

        const titleEl = document.createElement('span');
        titleEl.className = 'card-title';
        titleEl.textContent = card.title;

        const delBtn = document.createElement('button');
        delBtn.className = 'card-del';
        delBtn.setAttribute('aria-label', 'Delete card');
        delBtn.innerHTML = '<svg width="16" height="16" viewBox="0 0 16 16" fill="currentColor"><path d="M4.5 3h7v1h-7V3zm0 2h7v7h-7V5zm1 2h1v4H5.5V7zm3 0h1v4H8.5V7zM4 3h8v1H4V3z"/></svg>';

        delBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          deleteCard(card.id);
        });

        cardEl.appendChild(titleEl);
        cardEl.appendChild(delBtn);

        // Drag events
        cardEl.addEventListener('dragstart', handleDragStart);
        cardEl.addEventListener('dragend', handleDragEnd);

        return cardEl;
      }

      // Render all cards
      function render() {
        // Clear all columns
        Object.values(columns).forEach(col => col.innerHTML = '');

        // Add cards to their columns
        cards.forEach(card => {
          const cardEl = createCardElement(card);
          columns[card.column].appendChild(cardEl);
        });

        updateCounts();
      }

      // Update card counts
      function updateCounts() {
        const counts = { todo: 0, doing: 0, done: 0 };
        cards.forEach(card => counts[card.column]++);

        document.querySelectorAll('.column').forEach(col => {
          const columnKey = col.dataset.column;
          const countEl = col.querySelector('.count');
          if (countEl) countEl.textContent = counts[columnKey];
        });
      }

      // Add card
      function addCard(title) {
        const trimmed = title.trim();
        if (!trimmed) return;

        const card = {
          id: generateId(),
          title: trimmed,
          column: 'todo'
        };

        cards.push(card);
        save();
        render();
      }

      // Delete card
      function deleteCard(id) {
        cards = cards.filter(card => card.id !== id);
        save();
        render();
      }

      // Move card to column
      function moveCard(id, targetColumn) {
        const card = cards.find(c => c.id === id);
        if (card && card.column !== targetColumn) {
          card.column = targetColumn;
          save();
          render();
        }
      }

      // Save to localStorage
      function save() {
        localStorage.setItem('kanban-cards', JSON.stringify(cards));
      }

      // Load from localStorage
      function load() {
        const stored = localStorage.getItem('kanban-cards');
        if (stored) {
          try {
            cards = JSON.parse(stored);
            // Validate structure
            cards = cards.filter(card => 
              card && typeof card.id === 'string' && 
              typeof card.title === 'string' && 
              ['todo', 'doing', 'done'].includes(card.column)
            );
          } catch (e) {
            cards = [];
          }
        }
      }

      // Drag handlers
      function handleDragStart(e) {
        draggedCard = this;
        this.classList.add('dragging');
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', this.dataset.id);
      }

      function handleDragEnd(e) {
        this.classList.remove('dragging');
        draggedCard = null;
        // Remove drag-over from all columns
        Object.values(columnElements).forEach(col => col.classList.remove('drag-over'));
      }

      function handleDragOver(e) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        this.classList.add('drag-over');
      }

      function handleDragLeave(e) {
        // Only remove if leaving the column entirely
        if (!this.contains(e.relatedTarget)) {
          this.classList.remove('drag-over');
        }
      }

      function handleDrop(e) {
        e.preventDefault();
        this.classList.remove('drag-over');

        const cardId = e.dataTransfer.getData('text/plain');
        const targetColumn = this.dataset.column;

        if (cardId) {
          moveCard(cardId, targetColumn);
        }
      }

      // Initialize drag handlers on columns
      Object.values(columnElements).forEach(col => {
        col.addEventListener('dragover', handleDragOver);
        col.addEventListener('dragleave', handleDragLeave);
        col.addEventListener('drop', handleDrop);
      });

      // Event listeners
      addCardBtn.addEventListener('click', () => {
        addCard(newCardInput.value);
        newCardInput.value = '';
        newCardInput.focus();
      });

      newCardInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          addCard(newCardInput.value);
          newCardInput.value = '';
        }
      });

      // Initialize
      load();
      render();
      newCardInput.focus();
    })();
  </script>
</body>
</html>
